<template>
  <div class="page dashboard-page">
    <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" />
    <header class="page-heading"><div><span class="eyebrow">TEST WORKBENCH</span><h1>数据概览</h1><p>从今天的任务和异常开始排查，点击数字直接进入过滤结果。</p></div><div class="actions"><el-button type="primary" plain :icon="DataAnalysis" @click="router.push('/version-comparison')">版本对比工作台</el-button><el-segmented v-model="days" :options="['7 天','30 天']" @change="load" /><el-button :icon="Refresh" :loading="loading" @click="load">刷新</el-button></div></header>
    <section class="metric-grid"><button class="metric danger" @click="openTasks({status:'failed'})"><b>今日失败任务</b><strong>{{today.failed}}</strong><small>查看失败任务</small></button><button class="metric alert" @click="openTasks({date:'today',errors:'1'})"><b>今日新增异常</b><strong>{{today.errors}}</strong><small>进入今日异常任务</small></button><button class="metric info" @click="openTasks({date:'today',errors:'1'})"><b>较昨日新增异常</b><strong>{{signedDelta}}</strong><small>昨日 {{yesterday.errors}} 条</small></button><button class="metric neutral" @click="openTasks({date:'today'})"><b>今日解析任务</b><strong>{{today.tasks}}</strong><small>查看今日任务</small></button></section>
    <section class="content-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">HOTSPOTS</span><h2>异常最多的项目 / 版本</h2><p>点击项目版本直接进入任务过滤结果。</p></div><el-button text @click="router.push('/tasks')">全部任务 <el-icon><ArrowRight /></el-icon></el-button></div><div v-if="ranked.length" class="rank-list"><button v-for="item in ranked" :key="item.key" class="rank-row" @click="openTasks({project:item.project,version:item.version})"><span>{{item.index}}</span><strong>{{item.project}}<small>{{item.version||'未填写版本'}} · {{item.tasks}} 个任务</small></strong><i><em :style="{width:`${Math.max(8,item.errors/maxRank*100)}%`}" /></i><b>{{item.errors}}</b><el-icon><ArrowRight /></el-icon></button></div><el-empty v-else description="暂无项目版本异常数据" :image-size="72" /></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">SINCE YESTERDAY</span><h2>问题变化</h2><p>今日异常量与昨日比较。</p></div></div><div class="change" :class="{up:delta>0,down:delta<0}"><strong>{{signedDelta}}</strong><span>{{delta>0?'比昨日增加':delta<0?'比昨日减少':'与昨日持平'}}</span></div><div class="change-detail"><div>今日异常<b>{{today.errors}}</b></div><div>昨日异常<b>{{yesterday.errors}}</b></div><div>今日失败<b>{{today.failed}}</b></div></div><el-button type="primary" plain class="full" @click="openTasks({date:'today',errors:'1'})">查看今日异常任务 <el-icon><ArrowRight /></el-icon></el-button></section></section>
    <section class="panel"><div class="panel-heading"><div><span class="eyebrow">RECENT TASKS</span><h2>最近解析任务</h2><p>点击任务进入详情。</p></div><el-button text @click="router.push('/tasks')">打开任务列表 <el-icon><ArrowRight /></el-icon></el-button></div><div v-if="recent.length" class="recent-list"><button v-for="task in recent" :key="task.task_id" class="recent-row" @click="openTask(task.task_id)"><i :class="task.status" /><strong>{{task.original_name||task.project_name||'未命名任务'}}<small>{{task.project_name||'未命名项目'}} · {{task.version||'未填写版本'}}</small></strong><span>{{Number(task.error_count||0)}} 条异常</span><time>{{formatDate(task.updated_at||task.created_at)}}</time><el-icon><ArrowRight /></el-icon></button></div><el-empty v-else description="暂无近期任务" :image-size="72" /></section>
  </div>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessageBox } from 'element-plus'
import { ArrowRight, DataAnalysis, Refresh } from '@element-plus/icons-vue'
import { getDashboardStats, getTasks } from '@/api/task'
const router=useRouter();const loading=ref(false);const error=ref('');const days=ref('7 天');const tasks=ref([]);const stats=ref({});const today=computed(()=>({tasks:Number(stats.value.today_tasks||0),failed:Number(stats.value.today_failed||0),errors:Number(stats.value.today_errors||0)}));const yesterday=computed(()=>({errors:Number(stats.value.yesterday_errors||0)}));const delta=computed(()=>today.value.errors-yesterday.value.errors);const signedDelta=computed(()=>delta.value>0?`+${delta.value}`:String(delta.value));const ranked=computed(()=>{const map=new Map();tasks.value.forEach(t=>{const e=Number(t.error_count||0);if(!e)return;const project=t.project_name||'未命名项目',version=t.version||'',key=`${project}::${version}`;const row=map.get(key)||{key,project,version,errors:0,tasks:0};row.errors+=e;row.tasks++;map.set(key,row)});return[...map.values()].sort((a,b)=>b.errors-a.errors).slice(0,8).map((x,i)=>({...x,index:String(i+1).padStart(2,'0')}))});const recent=computed(()=>(stats.value.recent_tasks||[]).slice(0,8));const openTasks=q=>router.push({path:'/tasks',query:q});const openTask=id=>id&&router.push({name:'TaskDetail',params:{taskId:id}});async function openProject(item){try{await ElMessageBox.confirm(`是否进入“${item.project}”的日志记录，并自动筛选当前项目？`,'查看项目日志',{confirmButtonText:'进入日志记录',cancelButtonText:'取消',type:'info'});router.push({path:'/log-records',query:{project:item.project}})}catch{}}const formatDate=v=>v?new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'-';async function load(){loading.value=true;error.value='';try{const data=await getDashboardStats(days.value==='30 天'?30:7);stats.value=data||{};const result=await getTasks({page:1,page_size:200,sort:'updated_at'});tasks.value=Array.isArray(result?.list)?result.list:[]}catch(e){error.value=e?.response?.data?.message||e?.message||'数据概览加载失败，请刷新重试'}finally{loading.value=false}}onMounted(load)
const captureRankClick=(event)=>{const button=event.target.closest?.('.rank-row');if(!button)return;const item=ranked.value.find(row=>row.index===button.querySelector('span')?.textContent?.trim());if(!item)return;event.preventDefault();event.stopImmediatePropagation();openProject(item)}
document.addEventListener('click',captureRankClick,true)
</script>
<style scoped>
.dashboard-page{height:100%;overflow:auto;padding:clamp(14px,2vw,26px);color:#e8edf2;background:linear-gradient(145deg,#14171b,#1b1f25 48%,#111418)}.page-heading,.panel,.metric{border:1px solid rgba(255,255,255,.14);border-radius:12px;background:rgba(255,255,255,.07);box-shadow:0 14px 40px rgba(0,0,0,.2)}.page-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;padding:20px;margin:14px 0}.eyebrow{display:block;margin-bottom:6px;color:#67e8f9;font:600 10px ui-monospace,monospace;letter-spacing:.14em}.page-heading h1,.panel h2{margin:0;color:#f5f7fa}.page-heading p,.panel p{margin:6px 0 0;color:#aeb7c3;font-size:12px}.actions{display:flex;gap:8px}.actions :deep(.el-segmented){--el-segmented-bg-color:rgba(0,0,0,.22);--el-segmented-item-selected-bg-color:rgba(6,182,212,.25);--el-segmented-item-selected-color:#a8f3fb}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.metric{display:grid;padding:16px;color:#e8edf2;text-align:left;cursor:pointer;transition:.2s}.metric:hover,.rank-row:hover,.recent-row:hover{border-color:rgba(103,232,249,.5);background:rgba(6,182,212,.11);transform:translateY(-1px)}.metric b{color:#aeb7c3;font-size:12px}.metric strong{margin:7px 0;font-size:29px;color:#f5f7fa}.metric small{color:#929eaa}.danger strong{color:#fb7185}.alert strong{color:#fbbf24}.info strong{color:#67e8f9}.neutral strong{color:#a78bfa}.content-grid{display:grid;grid-template-columns:1.55fr .75fr;gap:14px;margin:14px 0}.panel{padding:18px;margin-bottom:14px}.panel-heading{display:flex;justify-content:space-between;gap:12px;margin-bottom:14px}.panel h2{font-size:16px}.rank-list,.recent-list{display:grid;gap:4px}.rank-row,.recent-row{display:flex;align-items:center;gap:10px;width:100%;padding:11px 8px;border:1px solid transparent;border-radius:8px;background:rgba(255,255,255,.035);color:#e8edf2;text-align:left;cursor:pointer}.rank-row>span{width:24px;color:#718096}.rank-row>strong,.recent-row>strong{display:grid;min-width:120px;flex:0 0 190px;gap:4px}.rank-row small,.recent-row small{color:#929eaa;font-size:11px;font-weight:400}.rank-row i{height:6px;flex:1;border-radius:4px;background:rgba(255,255,255,.1);overflow:hidden}.rank-row i em{display:block;height:100%;border-radius:4px;background:#fb7185}.rank-row>b{width:38px;color:#fb7185;text-align:right}.change{display:flex;align-items:baseline;gap:8px;margin:24px 0;color:#fb7185}.change.down{color:#6ee7b7}.change strong{font-size:42px}.change span{color:#aeb7c3;font-size:12px}.change-detail{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:16px}.change-detail div{padding:11px;border:1px solid rgba(255,255,255,.1);border-radius:8px;color:#929eaa;font-size:11px}.change-detail b{display:block;margin-top:5px;color:#f5f7fa;font-size:18px}.full{width:100%}.recent-row>i{width:8px;height:8px;border-radius:50%;background:#718096}.recent-row>i.failed{background:#fb7185}.recent-row>i.completed{background:#6ee7b7}.recent-row>strong{flex:1}.recent-row>span{width:70px;color:#fb7185;font-size:11px;text-align:right}.recent-row time{width:105px;color:#929eaa;font-size:11px;text-align:right}@media(max-width:950px){.metric-grid{grid-template-columns:repeat(2,1fr)}.content-grid{grid-template-columns:1fr}}@media(max-width:560px){.page-heading{align-items:stretch;flex-direction:column}.actions{width:100%}.actions :deep(.el-segmented){flex:1}.metric-grid{gap:8px}.metric{padding:12px 10px}.metric strong{font-size:23px}.panel{padding:14px}.rank-row>strong{flex-basis:125px}.recent-row time{display:none}}
</style>
<style scoped>.rank-row i{display:none!important}.rank-row>b{margin-left:auto;width:auto!important;white-space:nowrap}</style>
<style scoped>
.dashboard-page > .page-heading { margin-top: 0; }
</style>
